function calcCost(r,seen=[]){if(!r||seen.includes(r.id))return 0;let sum=0;for(const row of (r.items||[])){const u=row.ref?calcCost(byId(row.ref),[...seen,r.id]) / Math.max(byId(row.ref)?.yield||1,1) *1000:(Number(state.prices[row.name])||0);sum+=u*(Number(row.grams)||0)/1000;}return sum}
function itemCost(row){if(row.ref){let ref=byId(row.ref);return ref?(calcCost(ref)/Math.max(ref.yield,1))*Number(row.grams):0}return (Number(state.prices[row.name])||0)*Number(row.grams)/1000}
