const BUYER_DEMO_KEY='fk_kitchen_demo_buyer_company_v1';
function buyerCompany(){
 try{const x=JSON.parse(localStorage.getItem(BUYER_DEMO_KEY)||'{}');
   return {company:String(x.company||'').slice(0,180),manager:String(x.manager||'').slice(0,140),position:String(x.position||'').slice(0,100)};
 }catch{return {company:'',manager:'',position:''}}
}
function companyReady(p){return Boolean(p.company.trim()&&p.manager.trim()&&p.position.trim())}
