function saveBuyerCompany(form){
 const data=new FormData(form);
 const p={company:String(data.get('company')||'').trim().slice(0,180),
          manager:String(data.get('manager')||'').trim().slice(0,140),
          position:String(data.get('position')||'').trim().slice(0,100)};
 if(!companyReady(p))return notify('Заполните организацию, ФИО и должность');
 try{localStorage.setItem(BUYER_DEMO_KEY,JSON.stringify(p))}
 catch{return notify('Не удалось сохранить данные в браузере')};
 document.getElementById('buyer-profile-preview').innerHTML=buyerProfilePreview(p);
 notify('Данные сохранены для всех демонстрационных ТТК');
}
